CREATE DATABASE NORTHWIND;
USE NORTHWIND;

CREATE TABLE CUSTOMER( 
    CUSTOMER_ID CHAR(5) PRIMARY KEY, 
    COMPANY_NAME VARCHAR(50) NOT NULL, 
    CONTACT_NAME VARCHAR(50) NOT NULL, 
    CONTACT_TITLE VARCHAR(50) NOT NULL, 
    ADDRESS VARCHAR(50) NOT NULL, 
    CITY VARCHAR(50) NOT NULL, 
    REGION VARCHAR(50), 
    POSTAL_CODE VARCHAR(50), 
    COUNTRY VARCHAR(50) NOT NULL, 
    PHONE VARCHAR(50) NOT NULL, 
    FAX VARCHAR(50) 
);

CREATE TABLE SUPPLIERS( 
    SUPPLIER_ID INT AUTO_INCREMENT PRIMARY KEY, 
    COMPANY_NAME VARCHAR(50) NOT NULL, 
    CONTACT_NAME VARCHAR(50) NOT NULL, 
    CONTACT_TITLE VARCHAR(50) NOT NULL, 
    ADDRESS VARCHAR(50) NOT NULL, 
    CITY VARCHAR(50) NOT NULL, 
    REGION VARCHAR(50), 
    POSTAL_CODE VARCHAR(50), 
    COUNTRY VARCHAR(50) NOT NULL, 
    PHONE VARCHAR(50) NOT NULL, 
    FAX VARCHAR(50), 
    HOME_PAGE VARCHAR(300) 
);

CREATE TABLE SHIPPERS( 
    SHIPPER_ID INT AUTO_INCREMENT PRIMARY KEY, 
    COMPANY_NAME VARCHAR(50) NOT NULL, 
    PHONE VARCHAR(50) NOT NULL 
);

CREATE TABLE REGIONS( 
    REGION_ID INT AUTO_INCREMENT PRIMARY KEY, 
    REGION_DESCRIPTION VARCHAR(50) NOT NULL 
);

CREATE TABLE CATEGORY( 
    CATEGORY_ID INT AUTO_INCREMENT PRIMARY KEY, 
    CATEGORY_NAME VARCHAR(80) NOT NULL, 
    CATEGORY_DESCRIPTION VARCHAR(100) NOT NULL 
);

CREATE TABLE PRODUCT( 
    PRODUCT_ID INT AUTO_INCREMENT PRIMARY KEY, 
    SUPPLIER_ID INT, FOREIGN KEY (SUPPLIER_ID) REFERENCES SUPPLIERS(SUPPLIER_ID),
    CATEGORY_ID INT, FOREIGN KEY (CATEGORY_ID) REFERENCES CATEGORY(CATEGORY_ID),
    PRODUCT_NAME VARCHAR(50) NOT NULL, 
    QUANTITY_PER_UNIT VARCHAR(100) NOT NULL, 
    UNIT_PRICE DECIMAL(10,2) NOT NULL, 
    UNITS_IN_STOCK INT, 
    UNITS_ON_ORDER INT, 
    REORDER_LEVEL INT, 
    DISCONTINUED INT
);

CREATE TABLE TERRITORY( 
    TERRITORY_ID INT AUTO_INCREMENT PRIMARY KEY, 
    TERRITORY_DESCRIPTION VARCHAR(50) NOT NULL, 
    REGION_ID INT, FOREIGN KEY (REGION_ID) REFERENCES REGIONS(REGION_ID)
);

CREATE TABLE EMPLOYEE_TERRITORY( 
    EMPLOYEE_ID INT AUTO_INCREMENT PRIMARY KEY, 
    TERRITORY_ID INT, FOREIGN KEY (TERRITORY_ID) REFERENCES TERRITORY(TERRITORY_ID)
);

CREATE TABLE ORDER_DETAILS( 
    ORDER_ID INT AUTO_INCREMENT PRIMARY KEY, 
    EMPLOYEE_ID INT, FOREIGN KEY (EMPLOYEE_ID) REFERENCES EMPLOYEE_TERRITORY(EMPLOYEE_ID),
    CUSTOMER_ID CHAR(5), FOREIGN KEY (CUSTOMER_ID) REFERENCES CUSTOMER(CUSTOMER_ID),
    ORDER_DATE DATE, 
    REQUIRED_DATE DATE, 
    SHIPPED_DATE INT, 
    SHIP_VIA VARCHAR(50) NOT NULL, 
    FREIGHT VARCHAR(50) NOT NULL, 
    SHIP_NAME VARCHAR(50) NOT NULL, 
    SHIP_ADDRESS VARCHAR(50) NOT NULL, 
    SHIP_CITY VARCHAR(50) NOT NULL, 
    SHIP_REGION VARCHAR(50), 
    SHIP_POSTAL_CODE VARCHAR(50), 
    SHIP_COUNTRY VARCHAR(50) NOT NULL   
);

CREATE TABLE ORDERS( 
    ORDER_ID INT, FOREIGN KEY (ORDER_ID) REFERENCES ORDER_DETAILS(ORDER_ID), 
    PRODUCT_ID INT, FOREIGN KEY (PRODUCT_ID) REFERENCES PRODUCT(PRODUCT_ID),
    QUANTITY INT NOT NULL, 
    DISCOUNT DECIMAL(5,2)    
);

CREATE TABLE EMPLOYER( 
    CUSTOMER_ID CHAR(5), FOREIGN KEY (CUSTOMER_ID) REFERENCES CUSTOMER(CUSTOMER_ID), 
    EMPLOYEE_ID INT,  FOREIGN KEY (EMPLOYEE_ID) REFERENCES EMPLOYEE_TERRITORY(EMPLOYEE_ID),
    ORDER_ID INT, FOREIGN KEY (ORDER_ID) REFERENCES ORDER_DETAILS(ORDER_ID),
    PRODUCT_ID INT, FOREIGN KEY (PRODUCT_ID) REFERENCES PRODUCT(PRODUCT_ID), 
    ORDER_DATE DATE, 
    LAST_NAME VARCHAR(50) NOT NULL, 
    SHIP_CITY VARCHAR(50) NOT NULL, 
    PRODUCT_NAME VARCHAR(50) NOT NULL, 
    DISCOUNT DECIMAL(5,2), 
    UNIT_PRICE DECIMAL(10,2), 
    SALES DECIMAL(38,4)
);

